-- Q25: Time-series player quarterly performance evolution
SELECT p.full_name, strftime('%Y', m.match_date) || '-Q' || ((strftime('%m', m.match_date) - 1) / 3 + 1) AS quarter, ROUND(AVG(bp.runs_scored), 2) AS quarterly_avg_runs, ROUND(AVG(bp.strike_rate), 2) AS quarterly_avg_sr, CASE WHEN AVG(bp.runs_scored) > 40 THEN 'Career Ascending' WHEN AVG(bp.runs_scored) > 25 THEN 'Career Stable' ELSE 'Career Declining' END AS career_phase FROM batting_performances bp JOIN matches m ON bp.match_id = m.match_id JOIN players p ON bp.player_id = p.player_id GROUP BY p.player_id, p.full_name, quarter;